import{_ as e,o as t,c as n,a0 as o}from"./chunks/framework.bcCluOOn.js";const p=JSON.parse('{"title":"AAYU Chat","description":"","frontmatter":{},"headers":[],"relativePath":"platform/chat.md","filePath":"platform/chat.md"}'),i={name:"platform/chat.md"};function s(r,a,l,c,d,h){return t(),n("div",null,[...a[0]||(a[0]=[o('<h1 id="aayu-chat" tabindex="-1">AAYU Chat <a class="header-anchor" href="#aayu-chat" aria-label="Permalink to &quot;AAYU Chat&quot;">​</a></h1><p><strong>Status: Experimental</strong></p><p>AAYU Chat is a conversational AI interface designed to build software architecture, not random code.</p><h2 id="talk-design-generate" tabindex="-1">Talk. Design. Generate. <a class="header-anchor" href="#talk-design-generate" aria-label="Permalink to &quot;Talk. Design. Generate.&quot;">​</a></h2><p>Instead of writing <code>.aayu</code> syntax manually, you can tell AAYU Chat what you want to build.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">aayu</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chat</span></span></code></pre></div><h3 id="_1-cross-question-engine" tabindex="-1">1. Cross Question Engine <a class="header-anchor" href="#_1-cross-question-engine" aria-label="Permalink to &quot;1. Cross Question Engine&quot;">​</a></h3><p>AAYU Chat doesn&#39;t just blindly accept your prompt. It uses a <strong>Data-Driven Question Graph</strong> to ask clarifying questions about your specific domain.</p><blockquote><p><strong>AAYU</strong>: &quot;Do you need a Multi-tenant hospital or a Single branch?&quot; <strong>AAYU</strong>: &quot;Do patients need a dashboard portal?&quot;</p></blockquote><h3 id="_2-intent-engine" tabindex="-1">2. Intent Engine <a class="header-anchor" href="#_2-intent-engine" aria-label="Permalink to &quot;2. Intent Engine&quot;">​</a></h3><p>Instead of writing raw application code directly, AAYU Chat builds an <strong>Intent Model</strong>. This model represents entities, features, and workflows in the abstract.</p><h3 id="_3-source-generation" tabindex="-1">3. Source Generation <a class="header-anchor" href="#_3-source-generation" aria-label="Permalink to &quot;3. Source Generation&quot;">​</a></h3><p>The Intent Model enforces strict translation into valid <code>.aayu</code> language syntax. This guarantees that AAYU Chat will <strong>never hallucinate invalid code</strong>. The generated code is always 100% syntactically correct and passed to the Builder API.</p><h2 id="workflow-example" tabindex="-1">Workflow Example <a class="header-anchor" href="#workflow-example" aria-label="Permalink to &quot;Workflow Example&quot;">​</a></h2><ol><li>Run <code>aayu chat</code></li><li>Enter &quot;Hospital&quot;</li><li>Answer domain-specific questions</li><li>Review the generated Architecture</li><li>Accept and auto-generate the full backend and frontend stack.</li></ol>',15)])])}const g=e(i,[["render",s]]);export{p as __pageData,g as default};
